<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/admin.css"><title>MiniVR Control</title></head><body><aside><div class="logo">MINI<span>VR</span></div><a class="active">◉ Панорамы</a><a href="/admin/tours.php">◇ Экскурсии</a><a href="/admin/music.php">♫ Музыка</a><a href="/">↗ Открыть сайт</a><a href="?logout=1">⏻ Выход</a></aside><main><header><div><small>CONTENT SYSTEM</small><h1>Панорамы</h1></div><a class="btn" href="/admin/panorama.php">＋ ЗАГРУЗИТЬ</a></header><div class="stats"><div><b><?=count($panos)?></b><span>ПАНОРАМ</span></div><div><b><?=count(array_filter($panos,fn($p)=>$p['published']))?></b><span>ОПУБЛИКОВАНО</span></div></div><div class="table"><?php foreach($panos as $p): ?><div class="row"><div class="mini" style="background-image:url('<?=htmlspecialchars($p['image'])?>')"></div><div class="grow"><b><?=htmlspecialchars($p['title'])?></b><small>/<?=$p['slug']?></small></div><span class="status"><?=$p['published']?'ONLINE':'DRAFT'?></span><a href="/viewer.php?id=<?=$p['id']?>" target="_blank">VIEW</a><a class="danger" href="?delete=<?=$p['id']?>" onclick="return confirm('Удалить?')">×</a></div><?php endforeach;?></div></main></body></html>